create table if not exists public.election_governance_reports(id uuid primary key default gen_random_uuid(),award_space_id uuid not null references public.award_spaces(id) on delete cascade,report_hash text not null,report_snapshot jsonb not null,status text not null default 'draft' check(status in('draft','submitted','approved','distributed')),prepared_by uuid references public.admins(id) on delete set null,prepared_at timestamptz not null default now(),submitted_at timestamptz,approved_at timestamptz,approved_by uuid references public.admins(id) on delete set null,approval_note text,distributed_at timestamptz,distributed_by uuid references public.admins(id) on delete set null,unique(award_space_id,report_hash));
create table if not exists public.election_governance_report_signoffs(id uuid primary key default gen_random_uuid(),report_id uuid not null references public.election_governance_reports(id) on delete cascade,admin_id uuid not null references public.admins(id) on delete cascade,decision text not null check(decision in('approved','rejected')),note text,decided_at timestamptz not null default now(),unique(report_id,admin_id));
create table if not exists public.election_governance_report_distributions(id uuid primary key default gen_random_uuid(),report_id uuid not null references public.election_governance_reports(id) on delete cascade,recipient_name text not null,recipient_role text,recipient_email text,channel text not null default 'manual',distributed_by uuid references public.admins(id) on delete set null,distributed_at timestamptz not null default now());
create index if not exists election_governance_reports_space_idx on public.election_governance_reports(award_space_id,prepared_at desc);
create index if not exists election_governance_report_distributions_report_idx on public.election_governance_report_distributions(report_id,distributed_at desc);
alter table public.election_governance_reports enable row level security;
alter table public.election_governance_report_signoffs enable row level security;
alter table public.election_governance_report_distributions enable row level security;
